int nextValue(const unsigned char *data, size_t totalBits, size_t *pos, int *out) {
    size_t start = *pos;
    if (start > totalBits) return -1;
    if (totalBits - start < 6) return 0;
    unsigned int L = getBits(data, start, 5);
    if (L == 0) return 0;
    size_t payload = start + 5;
    if (L > totalBits - payload) return -1;
    unsigned int raw = getBits(data, payload, L);
    *out = decodeSigned(raw, L);
    *pos = payload + L;
    return 1;
}

